#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double weight=5,m=0,v=0,beta1=0.9,beta2=0.999,rate=0.1;
    for (int t=1;t<=100;t++){
        double gradient=2*(weight-3);
        m=beta1*m+(1-beta1)*gradient;
        v=beta2*v+(1-beta2)*gradient*gradient;
        double mCorrected=m/(1-pow(beta1,t));
        double vCorrected=v/(1-pow(beta2,t));
        weight-=rate*mCorrected/(sqrt(vCorrected)+1e-8);
    }
    cout<<fixed<<setprecision(6)<<weight<<"\n";
    return 0;
}

