    int total=0;
    for (int k=0;k<n;k++){
        int u=-1;
        for (int i=0;i<n;i++)if (!used[i]&&(u==-1||distance[i]<distance[u]))u=i;
        if (u==-1||distance[u]>=1000000)return 1;
        used[u]=1;
        total+=distance[u];
