#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <queue>
using namespace std;

int main(){
    int n=4,source=0,sink=3;
    int residual[4][4]={{0,3,2,0},{0,0,1,2},{0,0,0,4},{0,0,0,0}};
    int maxFlow=0;
    while (true){
        vector<int>parent(n,-1);
        queue<int>q;
        q.push(source);
        parent[source]=source;
        while (!q.empty()&&parent[sink]<0){
            int u=q.front();
            q.pop();
            for (int v=0;v<n;v++)if (parent[v]<0&&residual[u][v]>0){
                parent[v]=u;
                q.push(v);
            }
        }
        if (parent[sink]<0)break;
        int flow=1000000;
        for (int v=sink;v!=source;v=parent[v])flow=min(flow,residual[parent[v]][v]);
        for (int v=sink;v!=source;v=parent[v]){
            residual[parent[v]][v]-=flow;
            residual[v][parent[v]]+=flow;
        }
        maxFlow+=flow;
    }
    cout<<maxFlow<<"\n";
    return 0;
}

