#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double reward[2][2]={{1,0},{0,2}},gamma=0.9;
    int next[2][2]={{0,1},{0,1}},policy[2]={0,0};
    double value[2]={0,0};
    for (int iteration=0;iteration<40;iteration++){
        for (int k=0;k<60;k++){
            double old0=value[0],old1=value[1];
            value[0]=reward[0][policy[0]]+gamma*(next[0][policy[0]]==0?old0:old1);
            value[1]=reward[1][policy[1]]+gamma*(next[1][policy[1]]==0?old0:old1);
        }
        bool changed=false;
        for (int s=0;s<2;s++){
            double q0=reward[s][0]+gamma*value[next[s][0]];
            double q1=reward[s][1]+gamma*value[next[s][1]];
            int best=q1>q0?1:0;
            if (best!=policy[s]){
                policy[s]=best;
                changed=true;
            }
        }
        if (!changed)break;
    }
    cout<<policy[0]<<" "<<policy[1]<<" "<<value[0]<<" "<<value[1]<<"\n";
    return 0;
}

