#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    double spot=100,u=1.1,d=0.9,strike=100,discount=1.02;
    double upper=max(0.0,strike-spot*u*u);
    double middle=max(0.0,strike-spot*u*d);
    double lower=max(0.0,strike-spot*d*d);
    double q=(discount-d)/(u-d);
    double putUp=max(max(0.0,strike-spot*u),(q*upper+(1-q)*middle)/discount);
    double putDown=max(max(0.0,strike-spot*d),(q*middle+(1-q)*lower)/discount);
    double value=max(max(0.0,strike-spot),(q*putUp+(1-q)*putDown)/discount);
    cout<<fixed<<setprecision(6)<<value<<"\n";
    return 0;
}

